package com.reelseries.android;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
import com.google.firebase.auth.*;import com.google.firebase.firestore.*;
public class ProfileActivity extends Activity {
 LinearLayout root; FirebaseAuth auth; FirebaseFirestore db; TextView identity, vip; int bg=0xff0c101b;
 int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 TextView label(String text,int size,int color){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(color);t.setPadding(dp(6),dp(12),dp(6),dp(12));return t;}
 void button(String text,View.OnClickListener click){Button b=new Button(this);b.setAllCaps(false);b.setText(text);b.setTextSize(16);root.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(click);}
 @Override public void onCreate(Bundle b){super.onCreate(b);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();getWindow().setStatusBarColor(bg);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(18),dp(22),dp(28));root.setBackgroundColor(bg);scroll.addView(root);setContentView(scroll);render();}
 void render(){root.removeAllViews();TextView title=label("◉  MEU PERFIL",27,0xffff4564);title.setTypeface(null,1);root.addView(title);identity=label("Conta não conectada",17,Color.WHITE);root.addView(identity);vip=label("Assinatura: não verificada",15,0xffb7c2d1);root.addView(vip);
 FirebaseUser user=auth.getCurrentUser();if(user!=null){identity.setText(user.getEmail()==null?"Usuário conectado":user.getEmail());db.collection("usuarios").document(user.getUid()).get().addOnSuccessListener(d->{if(isFinishing())return;String name=d.getString("nome");if(name!=null&&!name.isEmpty())identity.setText(name+"\n"+user.getEmail());Boolean active=d.getBoolean("vipAtivo");vip.setText(Boolean.TRUE.equals(active)?"VIP informado como ativo no Firebase":"VIP não ativo ou não configurado");}).addOnFailureListener(e->vip.setText("Não foi possível consultar a assinatura"));button("Sair da conta",v->{auth.signOut();render();});}
 else{EditText email=new EditText(this);email.setSingleLine();email.setHint("E-mail");email.setTextColor(-1);email.setHintTextColor(0xffaaaaaa);root.addView(email);EditText pass=new EditText(this);pass.setHint("Senha");pass.setTextColor(-1);pass.setHintTextColor(0xffaaaaaa);pass.setInputType(129);root.addView(pass);TextView msg=label("",13,0xffff8b96);root.addView(msg);button("Entrar",v->auth.signInWithEmailAndPassword(email.getText().toString().trim(),pass.getText().toString()).addOnSuccessListener(r->render()).addOnFailureListener(e->msg.setText(e.getMessage())));button("Criar conta",v->auth.createUserWithEmailAndPassword(email.getText().toString().trim(),pass.getText().toString()).addOnSuccessListener(r->render()).addOnFailureListener(e->msg.setText(e.getMessage())));}
 root.addView(label("MINHA BIBLIOTECA",19,Color.WHITE));button("♥  Minha lista",v->showFavorites());button("▶  Continuar assistindo",v->showContinue());button("♛  Minha assinatura",v->showSubscription());button("⚙  Configurações",v->new AlertDialog.Builder(this).setItems(new String[]{"Sobre o aplicativo","Voltar"},(d,w)->{if(w==0)new AlertDialog.Builder(this).setMessage("Reel Séries Android Nativo V6").setPositiveButton("OK",null).show();}).show());button("🛡  Administração",v->startActivity(new Intent(this,AdminActivity.class)));button("←  Voltar ao catálogo",v->finish());}
 void openTitle(String name){Intent i=new Intent(this,MainActivity.class);i.putExtra("reel_search_title",name);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);finish();}
 void showFavorites(){android.content.SharedPreferences prefs=getSharedPreferences("reel_favorites",MODE_PRIVATE);java.util.ArrayList<String> names=new java.util.ArrayList<>();for(java.util.Map.Entry<String,?> e:prefs.getAll().entrySet())if(Boolean.TRUE.equals(e.getValue()))names.add(e.getKey());java.util.Collections.sort(names);if(names.isEmpty()){new AlertDialog.Builder(this).setTitle("Minha lista").setMessage("Nenhum título salvo ainda. Abra um filme ou série e toque em Adicionar aos favoritos.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(this).setTitle("Minha lista • "+names.size()+" títulos").setItems(names.toArray(new String[0]),(d,w)->openTitle(names.get(w))).setNegativeButton("Fechar",null).show();}
 void showContinue(){
  android.content.SharedPreferences prefs=getSharedPreferences("reel_continue_history",MODE_PRIVATE);
  java.util.ArrayList<org.json.JSONObject> items=new java.util.ArrayList<>();
  for(Object value:prefs.getAll().values())if(value instanceof String){try{org.json.JSONObject o=new org.json.JSONObject((String)value);if(o.optString("url").startsWith("http")&&o.optLong("position")>=5000)items.add(o);}catch(Exception ignored){}}
  java.util.Collections.sort(items,(a,b)->Long.compare(b.optLong("updated"),a.optLong("updated")));
  if(items.isEmpty()){new AlertDialog.Builder(this).setTitle("Continuar assistindo").setMessage("Nenhum vídeo em andamento. Assista a um filme ou episódio por alguns segundos para aparecer aqui.").setPositiveButton("OK",null).show();return;}
  String[] labels=new String[items.size()];for(int i=0;i<items.size();i++){org.json.JSONObject o=items.get(i);long secs=o.optLong("position")/1000;labels[i]=o.optString("name","Vídeo")+"  •  "+(secs/60)+"min "+(secs%60)+"s";}
  new AlertDialog.Builder(this).setTitle("Continuar assistindo").setItems(labels,(d,w)->{org.json.JSONObject o=items.get(w);Intent intent=new Intent(this,PlayerActivity.class);intent.putExtra("url",o.optString("url"));intent.putExtra("name",o.optString("name","Vídeo"));startActivity(intent);}).setNegativeButton("Fechar",null).show();
 }
 void showSubscription(){FirebaseUser u=auth.getCurrentUser();if(u==null){new AlertDialog.Builder(this).setTitle("Minha assinatura").setMessage("Entre na sua conta para consultar a assinatura.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(this).setTitle("Minha assinatura").setMessage(vip.getText().toString()).setPositiveButton("OK",null).show();}
}
